def is_acyclic(selected, features):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dep in selected[name].get('deps', []):
            feature = dep.get('feature')
            if feature not in (None, '') and feature not in features:
                continue
            dep_name = dep['name']
            if dep_name not in selected or not visit(dep_name):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in selected)
